import { useContext, useState, useMemo } from 'react';
import { Sidebar } from '@/components/dashboard/Sidebar';
import { Header } from '@/components/dashboard/Header';
import { Card, CardHeader, CardTitle, CardDescription, CardContent } from '@/components/ui/Card';
import { Button } from '@/components/ui/Button';
import { Badge } from '@/components/ui/Badge';
import {
  DollarSign,
  TrendingUp,
  Calendar,
  Download,
  Eye,
  CheckCircle,
  Clock,
  Users,
  Navigation,
  ArrowUpRight,
  ArrowDownRight,
} from 'lucide-react';
import userContext from "../../../context/userContext";
import useEarning from '../../../hooks/drivers/get/useEarning';

export default function DriverEarnings() {
  const [selectedPeriod, setSelectedPeriod] = useState('month');
  const { user, logOut }: any = useContext(userContext);
  const currentYear = new Date().getFullYear();
  const { data: earningData, isLoading, isError } = useEarning(currentYear);

  // Normalize earnings data from API
  const normalizedEarnings = useMemo(() => {
    if (!earningData) {
      return {
        monthlyEarnings: [],
        recentTransactions: [],
        studentBreakdown: [],
        stats: [],
      };
    }

    // Extract API data - handle both array and object responses
    const earnings = Array.isArray(earningData) ? earningData : earningData.earnings || [];
    const transactions = earningData.transactions || [];
    const students = earningData.students || [];

    // Helper to get month name from ISO format (2026-02)
    const getMonthName = (monthStr: string) => {
      if (!monthStr) return 'Unknown';
      const months = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];
      const match = monthStr.match(/(\d{4})-(\d{2})/);
      if (match) {
        const monthNum = parseInt(match[2]) - 1;
        return months[monthNum] || 'Unknown';
      }
      return monthStr;
    };

    // Helper to check if month is current
    const isCurrentMonth = (monthStr: string) => {
      if (!monthStr) return false;
      const today = new Date();
      const currentISOMonth = `${today.getFullYear()}-${String(today.getMonth() + 1).padStart(2, '0')}`;
      return monthStr === currentISOMonth;
    };

    // Normalize monthly earnings
    const monthlyEarnings = earnings.map((e: any) => ({
      month: getMonthName(e.month),
      amount: parseInt(e.total || e.amount || e.total_earning || 0),
      routes: parseInt(e.route_count || e.routes || e.total_routes || 0),
      students: parseInt(e.child_count || e.students || e.total_students || 0),
      avgPerRoute: e.route_count ? Math.round(parseInt(e.total || 0) / parseInt(e.route_count)) : 0,
      current: isCurrentMonth(e.month),
      activeChildCount: parseInt(e.active_child_count || e.active_students || 0),
    }));

    // Normalize transactions
    const recentTransactions = transactions.map((t: any, idx: number) => ({
      id: t.id || `TXN-${Date.now()}-${idx}`,
      date: t.date || t.transaction_date || new Date().toISOString().split('T')[0],
      description: t.description || `Route ${t.route_name || 'A'}`,
      amount: parseInt(t.amount || 0),
      status: t.status || 'completed',
      students: parseInt(t.students || t.total_students || 0),
      routes: parseInt(t.routes || 1),
    }));

    // Normalize student breakdown
    const studentBreakdown = students.map((s: any) => ({
      name: s.name || s.full_name || 'Unknown Student',
      monthlyFee: parseInt(s.monthly_fee || s.fee || 0),
      status: s.payment_status || s.status || 'paid',
      route: s.route || s.route_name || 'Route A',
    }));

    // Calculate stats
    const totalEarned = monthlyEarnings.reduce((sum: number, m: any) => sum + m.amount, 0);
    const currentMonth = monthlyEarnings.find((m: any) => m.current);
    const avgPerRoute =
      monthlyEarnings.length > 0
        ? Math.round(
            monthlyEarnings.reduce((sum: number, m: any) => sum + m.avgPerRoute, 0) /
              monthlyEarnings.length
          )
        : 0;

    const stats = [
      {
        title: 'This Month',
        value: `Rs.${currentMonth?.amount || 0}`,
        change: '+12%',
        trend: 'up',
        icon: DollarSign,
        color: 'text-green-600',
        bgColor: 'bg-green-50',
      },
      {
        title: 'Total Earned',
        value: `Rs.${totalEarned}`,
        change: '+8%',
        trend: 'up',
        icon: TrendingUp,
        color: 'text-primary',
        bgColor: 'bg-primary-50',
      },
      {
        title: 'Avg Per Route',
        value: `Rs.${avgPerRoute}`,
        change: '+5%',
        trend: 'up',
        icon: Navigation,
        color: 'text-secondary',
        bgColor: 'bg-secondary-50',
      },
      {
        title: 'Active Students',
        value: `${monthlyEarnings.reduce((sum: number, m: any) => sum + m.activeChildCount, 0)}`,
        change: '+2',
        trend: 'up',
        icon: Users,
        color: 'text-highlight',
        bgColor: 'bg-highlight-50',
      },
    ];

    return {
      monthlyEarnings,
      recentTransactions,
      studentBreakdown,
      stats,
    };
  }, [earningData]);

  const { monthlyEarnings: apiMonthlyEarnings, recentTransactions: apiRecentTransactions, studentBreakdown: apiStudentBreakdown, stats } = normalizedEarnings;

  // Fallback to mock data if API data is not available
  const displayMonthlyEarnings = apiMonthlyEarnings.length > 0 ? apiMonthlyEarnings : [
    { month: 'January', amount: 2200, routes: 44, students: 11, avgPerRoute: 50 },
    { month: 'February', amount: 2100, routes: 42, students: 11, avgPerRoute: 50 },
    { month: 'March', amount: 2300, routes: 46, students: 12, avgPerRoute: 50 },
    { month: 'April', amount: 2250, routes: 45, students: 12, avgPerRoute: 50 },
    { month: 'May', amount: 2400, routes: 48, students: 12, avgPerRoute: 50 },
    { month: 'June', amount: 2350, routes: 47, students: 12, avgPerRoute: 50 },
    { month: 'July', amount: 2200, routes: 44, students: 11, avgPerRoute: 50 },
    { month: 'August', amount: 2500, routes: 50, students: 12, avgPerRoute: 50 },
    { month: 'September', amount: 2450, routes: 49, students: 12, avgPerRoute: 50 },
    { month: 'October', amount: 2450, routes: 48, students: 12, avgPerRoute: 51, current: true },
  ];

  const displayRecentTransactions = apiRecentTransactions.length > 0 ? apiRecentTransactions : [
    {
      id: 'TXN-2025-10-001',
      date: '2025-10-09',
      description: 'Route A - Morning & Afternoon',
      amount: 102,
      status: 'completed',
      students: 12,
      routes: 2,
    },
    {
      id: 'TXN-2025-10-002',
      date: '2025-10-08',
      description: 'Route A - Morning & Afternoon',
      amount: 102,
      status: 'completed',
      students: 12,
      routes: 2,
    },
    {
      id: 'TXN-2025-10-003',
      date: '2025-10-07',
      description: 'Route A - Morning & Afternoon',
      amount: 102,
      status: 'completed',
      students: 12,
      routes: 2,
    },
    {
      id: 'TXN-2025-10-004',
      date: '2025-10-06',
      description: 'Route A - Morning & Afternoon',
      amount: 102,
      status: 'pending',
      students: 12,
      routes: 2,
    },
    {
      id: 'TXN-2025-10-005',
      date: '2025-10-05',
      description: 'Route A - Morning & Afternoon',
      amount: 102,
      status: 'completed',
      students: 12,
      routes: 2,
    },
  ];

  const displayStudentBreakdown = apiStudentBreakdown.length > 0 ? apiStudentBreakdown : [
    { name: 'Emma Johnson', monthlyFee: 120, status: 'paid', route: 'Route A' },
    { name: 'Oliver Johnson', monthlyFee: 120, status: 'paid', route: 'Route A' },
    { name: 'Sophia Davis', monthlyFee: 120, status: 'paid', route: 'Route A' },
    { name: 'Liam Wilson', monthlyFee: 120, status: 'paid', route: 'Route A' },
    { name: 'Ava Martinez', monthlyFee: 120, status: 'paid', route: 'Route A' },
    { name: 'Noah Anderson', monthlyFee: 120, status: 'paid', route: 'Route A' },
    { name: 'Mia Taylor', monthlyFee: 120, status: 'pending', route: 'Route A' },
    { name: 'Ethan Brown', monthlyFee: 120, status: 'paid', route: 'Route A' },
    { name: 'Isabella Garcia', monthlyFee: 120, status: 'paid', route: 'Route A' },
    { name: 'Lucas Martinez', monthlyFee: 120, status: 'paid', route: 'Route A' },
    { name: 'Charlotte Lee', monthlyFee: 120, status: 'paid', route: 'Route A' },
    { name: 'Mason White', monthlyFee: 120, status: 'paid', route: 'Route A' },
  ];

  const maxAmount = Math.max(...displayMonthlyEarnings.map((m: any) => m.amount));

  return (
    <div className="flex min-h-screen bg-neutral-50">
      <Sidebar
        userRole={user?.role || "Guest"}
        userName={user?.full_name || "Zaman Ali"}
        userEmail={user?.email || "zaman.ali@example.com"}
        logOut={logOut}
      />

      <div className="flex-1">
        <Header title="Earnings Report" subtitle="Track your income and financial performance" role={user?.role}
          profile={user?.profile_photo || ""}/>

        {isError && (
          <div className="p-6 bg-accent/10 border border-accent text-accent rounded-lg m-6">
            Failed to load earnings data. Showing cached data.
          </div>
        )}

        <main className="p-6">
          {isLoading && (
            <div className="flex items-center justify-center py-12">
              <p className="text-neutral-600">Loading earnings data...</p>
            </div>
          )}

          {!isLoading && (
            <>
              {/* Stats Grid */}
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6 mb-8">
                {stats.map((stat, index) => (
                  <Card key={index} hover>
                    <CardContent className="p-6">
                      <div className="flex items-center justify-between mb-4">
                        <div className={`w-12 h-12 ${stat.bgColor} rounded-xl flex items-center justify-center`}>
                          <stat.icon className={`w-6 h-6 ${stat.color}`} />
                        </div>
                        <div className="flex items-center gap-1 text-xs">
                          {stat.trend === 'up' ? (
                            <ArrowUpRight className="w-4 h-4 text-green-600" />
                          ) : (
                            <ArrowDownRight className="w-4 h-4 text-accent" />
                          )}
                          <span className={stat.trend === 'up' ? 'text-green-600' : 'text-accent'}>
                            {stat.change}
                          </span>
                        </div>
                      </div>
                      <h3 className="text-2xl font-bold text-neutral-900 mb-1">{stat.value}</h3>
                      <p className="text-sm text-neutral-600">{stat.title}</p>
                    </CardContent>
                  </Card>
            ))}
          </div>

          <div className="grid lg:grid-cols-3 gap-6">
            {/* Earnings Chart */}
            <div className="lg:col-span-2 space-y-6">
              <Card>
                <CardHeader>
                  <div className="flex items-center justify-between">
                    <div>
                      <CardTitle>Earnings Overview</CardTitle>
                      <CardDescription>Monthly earnings for {currentYear}</CardDescription>
                    </div>
                    <div className="flex gap-2">
                      <Button
                        variant={selectedPeriod === 'month' ? 'primary' : 'outline'}
                        size="sm"
                        onClick={() => setSelectedPeriod('month')}
                      >
                        Month
                      </Button>
                      <Button
                        variant={selectedPeriod === 'year' ? 'primary' : 'outline'}
                        size="sm"
                        onClick={() => setSelectedPeriod('year')}
                      >
                        Year
                      </Button>
                    </div>
                  </div>
                </CardHeader>
                <CardContent>
                  {/* Simple Bar Chart */}
                  <div className="space-y-3">
                    {displayMonthlyEarnings.map((item: any, index: number) => (
                      <div key={index} className="space-y-2">
                        <div className="flex items-center justify-between text-sm">
                          <span className={`font-medium ${item.current ? 'text-primary' : 'text-neutral-700'}`}>
                            {item.month}
                            {item.current && (
                              <Badge variant="primary" className="ml-2 text-xs">
                                Current
                              </Badge>
                            )}
                          </span>
                          <span className="font-bold text-neutral-900">Rs.{item.amount}</span>
                        </div>
                        <div className="relative w-full h-8 bg-neutral-100 rounded-lg overflow-hidden">
                          <div
                            className={`h-full rounded-lg transition-all duration-500 ${
                              item.current
                                ? 'bg-gradient-to-r from-primary to-secondary'
                                : 'bg-neutral-300'
                            }`}
                            style={{ width: `${(item.amount / maxAmount) * 100}%` }}
                          />
                          <div className="absolute inset-0 flex items-center px-3 text-xs text-neutral-100">
                            {item.routes} routes • {item.students} students
                          </div>
                        </div>
                      </div>
                    ))}
                  </div>
                </CardContent>
              </Card>

              {/* Recent Transactions */}
              <Card>
                <CardHeader>
                  <div className="flex items-center justify-between">
                    <div>
                      <CardTitle>Recent Transactions</CardTitle>
                      <CardDescription>Your latest earnings</CardDescription>
                    </div>
                    <Button variant="outline" size="sm">
                      <Download className="w-4 h-4" />
                      Export
                    </Button>
                  </div>
                </CardHeader>
                <CardContent>
                  <div className="space-y-3">
                    {displayRecentTransactions.map((transaction: any) => (
                      <div
                        key={transaction.id}
                        className="flex items-center justify-between p-4 border border-neutral-200 rounded-lg hover:border-neutral-300 transition-colors"
                      >
                        <div className="flex-1">
                          <div className="flex items-center gap-3 mb-1">
                            <p className="font-semibold text-neutral-900">{transaction.id}</p>
                            <Badge variant={transaction.status === 'completed' ? 'success' : 'warning'}>
                              {transaction.status === 'completed' ? (
                                <CheckCircle className="w-3 h-3" />
                              ) : (
                                <Clock className="w-3 h-3" />
                              )}
                              {transaction.status.charAt(0).toUpperCase() + transaction.status.slice(1)}
                            </Badge>
                          </div>
                          <p className="text-sm text-neutral-600 mb-1">{transaction.description}</p>
                          <div className="flex items-center gap-4 text-xs text-neutral-500">
                            <span>{transaction.date}</span>
                            <span>•</span>
                            <span>{transaction.routes} routes</span>
                            <span>•</span>
                            <span>{transaction.students} students</span>
                          </div>
                        </div>
                        <div className="text-right">
                          <p className="text-xl font-bold text-green-600">${transaction.amount}</p>
                        </div>
                      </div>
                    ))}
                  </div>
                </CardContent>
              </Card>
            </div>

            {/* Right Sidebar */}
            <div className="space-y-6">
              {/* Payment Summary */}
              <Card className="bg-gradient-to-br from-primary to-secondary text-white">
                <CardContent className="p-6">
                  {(() => {
                    const currentOrLatest = displayMonthlyEarnings.find((m: any) => m.current) || displayMonthlyEarnings[displayMonthlyEarnings.length - 1];
                    return (
                      <>
                        <h3 className="text-lg font-semibold mb-4">{currentOrLatest?.month} {new Date().getFullYear()}</h3>
                        <div className="space-y-4">
                          <div>
                            <p className="text-white/80 text-sm mb-1">Total Earnings</p>
                            <p className="text-3xl font-bold">Rs.{currentOrLatest?.amount || 0}</p>
                          </div>
                          <div className="pt-4 border-t border-white/20">
                            <div className="flex items-center justify-between mb-2">
                              <span className="text-white/80 text-sm">Completed Routes</span>
                              <span className="font-semibold">{currentOrLatest?.routes || 0}</span>
                            </div>
                            <div className="flex items-center justify-between mb-2">
                              <span className="text-white/80 text-sm">Active Students</span>
                              <span className="font-semibold">{currentOrLatest?.students || 0}</span>
                            </div>
                            <div className="flex items-center justify-between">
                              <span className="text-white/80 text-sm">Avg Per Route</span>
                              <span className="font-semibold">Rs.{currentOrLatest?.avgPerRoute || 0}</span>
                            </div>
                          </div>
                        </div>
                      </>
                    );
                  })()}
                </CardContent>
              </Card>

              {/* Student Breakdown */}
              <Card>
                <CardHeader>
                  <CardTitle>Student Breakdown</CardTitle>
                  <CardDescription>Monthly fees per student</CardDescription>
                </CardHeader>
                <CardContent>
                  <div className="space-y-2 max-h-96 overflow-y-auto scrollbar-hide">
                    {displayStudentBreakdown.map((student: any, index: number) => (
                      <div
                        key={index}
                        className="flex items-center justify-between p-3 bg-neutral-50 rounded-lg"
                      >
                        <div className="flex-1 min-w-0">
                          <p className="text-sm font-medium text-neutral-900 truncate">
                            {student.name}
                          </p>
                          <p className="text-xs text-neutral-600">{student.route}</p>
                        </div>
                        <div className="flex items-center gap-2">
                          <p className="text-sm font-bold text-neutral-900">${student.monthlyFee}</p>
                          {student.status === 'paid' ? (
                            <CheckCircle className="w-4 h-4 text-green-500" />
                          ) : (
                            <Clock className="w-4 h-4 text-highlight" />
                          )}
                        </div>
                      </div>
                    ))}
                  </div>
                  <div className="mt-4 pt-4 border-t border-neutral-200">
                    <div className="flex items-center justify-between">
                      <span className="font-semibold text-neutral-900">Total Monthly</span>
                      <span className="text-xl font-bold text-primary">
                        ${displayStudentBreakdown.reduce((acc: number, s: any) => acc + s.monthlyFee, 0)}
                      </span>
                    </div>
                  </div>
                </CardContent>
              </Card>

              {/* Quick Actions */}
              <Card>
                <CardHeader>
                  <CardTitle>Quick Actions</CardTitle>
                </CardHeader>
                <CardContent>
                  <div className="space-y-2">
                    <Button variant="outline" className="w-full justify-start">
                      <Download className="w-4 h-4" />
                      Download Report
                    </Button>
                    <Button variant="outline" className="w-full justify-start">
                      <Eye className="w-4 h-4" />
                      View All Transactions
                    </Button>
                    <Button variant="outline" className="w-full justify-start">
                      <Calendar className="w-4 h-4" />
                      Payment History
                    </Button>
                  </div>
                </CardContent>
              </Card>
            </div>
          </div>
            </>
          )}
        </main>
      </div>
    </div>
  );
}
