import React from "react";
import { Bell, Search, User } from "lucide-react";
import { Button } from "@/components/ui/Button";
import { Avatar } from "@/components/ui/Avatar";
import { getFileUrl } from "../../api/apiConstant";

interface HeaderProps {
  title: string;
  subtitle?: string;
  role?: string;
  profile?: string;
}

export const Header = ({ title, subtitle, role, profile }: HeaderProps) => {
  return (
    <header className="bg-white border-b border-neutral-200 px-6 py-4">
      <div className="flex items-center justify-between">
        {/* Title Section */}
        <div>
          <h1 className="text-2xl font-bold text-neutral-900">{title}</h1>
          {subtitle && (
            <p className="text-sm text-neutral-600 mt-1">{subtitle}</p>
          )}
        </div>

        {/* Actions Section */}
        <div className="flex items-center gap-3">
          {/* Search Button */}
          <Button variant="ghost" size="sm">
            <Search className="w-4 h-4" />
          </Button>

          {/* Notifications */}
          <Button variant="ghost" size="sm" className="relative">
            <Bell className="w-4 h-4" />
            <span className="absolute -top-1 -right-1 w-3 h-3 bg-accent rounded-full"></span>
          </Button>

          {/* User Profile */}
          <div className="flex items-center gap-2 pl-3 border-l border-neutral-200">
            {profile ? (
              <Avatar src={getFileUrl(profile)} size="sm" />
            ) : (
              <Avatar name={role || "User"} size="sm" />
            )}
            <div className="hidden md:block">
              <p className="text-sm font-medium text-neutral-900">{role}</p>
              <p className="text-xs text-neutral-600">Online</p>
            </div>
          </div>
        </div>
      </div>
    </header>
  );
};
