import React, { useState } from 'react';
import { Sidebar } from '@/components/dashboard/Sidebar';
import { Header } from '@/components/dashboard/Header';
import { Card, CardHeader, CardTitle, CardDescription, CardContent } from '@/components/ui/Card';
import { Button } from '@/components/ui/Button';
import { Badge } from '@/components/ui/Badge';
import { Avatar } from '@/components/ui/Avatar';
import {
  MessageSquare,
  AlertTriangle,
  CheckCircle,
  Clock,
  User,
  Calendar,
  FileText,
  Eye,
  Trash2,
  Send,
  X,
  Reply,
} from 'lucide-react';
import { useContext } from 'react';
import userContext from '../../../context/userContext';

export default function SchoolComplaints() {
  const [selectedComplaint, setSelectedComplaint] = useState<number | null>(null);
  const [filterStatus, setFilterStatus] = useState<'all' | 'open' | 'resolved' | 'in-progress'>('all');
  const [filterPriority, setFilterPriority] = useState<'all' | 'high' | 'medium' | 'low'>('all');
  const [searchQuery, setSearchQuery] = useState('');
  const [replyText, setReplyText] = useState('');
  const { user }: any = useContext(userContext);

  const complaints = [
    {
      id: 1,
      complaintId: 'C-2026-001',
      driverId: 1,
      driverName: 'Ahmad Hassan Khan',
      category: 'Safety Concern',
      subject: 'Speeding on school route',
      description: 'Driver was speeding near school zone, putting students at risk.',
      priority: 'high',
      status: 'open',
      submittedDate: '2026-02-23',
      submittedBy: 'Parent - Ali Ahmed',
      studentName: 'Ahmed Khan (Class 5)',
      responses: [
        {
          date: '2026-02-23',
          message: 'We are aware of this issue and investigating.',
          from: 'School Admin',
        },
      ],
    },
    {
      id: 2,
      complaintId: 'C-2026-002',
      driverId: 2,
      driverName: 'Muhammad Ali Syed',
      category: 'Behavior',
      subject: 'Rude behavior towards students',
      description: 'Driver was rude and dismissive when students asked a question.',
      priority: 'medium',
      status: 'in-progress',
      submittedDate: '2026-02-22',
      submittedBy: 'Parent - Fatima Khan',
      studentName: 'Sara Khan (Class 3)',
      responses: [
        {
          date: '2026-02-22',
          message: 'We have spoken to the driver about this incident.',
          from: 'School Admin',
        },
        {
          date: '2026-02-23',
          message: 'Driver apologizes and will improve behavior.',
          from: 'Driver Representative',
        },
      ],
    },
    {
      id: 3,
      complaintId: 'C-2026-003',
      driverId: 3,
      driverName: 'Fatima Abdullah',
      category: 'Cleanliness',
      subject: 'Van not clean',
      description: 'Van interior was not properly cleaned, seats had trash.',
      priority: 'low',
      status: 'resolved',
      submittedDate: '2026-02-20',
      submittedBy: 'Parent - Hassan Ali',
      studentName: 'Ali Hassan (Class 4)',
      responses: [
        {
          date: '2026-02-20',
          message: 'Received complaint about cleanliness.',
          from: 'School Admin',
        },
        {
          date: '2026-02-21',
          message: 'Van has been thoroughly cleaned.',
          from: 'Driver Representative',
        },
        {
          date: '2026-02-22',
          message: 'Issue resolved. Driver will maintain daily cleaning.',
          from: 'School Admin',
        },
      ],
    },
    {
      id: 4,
      complaintId: 'C-2026-004',
      driverId: 2,
      driverName: 'Muhammad Ali Syed',
      category: 'Timing',
      subject: 'Frequent delays',
      description: 'Driver is consistently late, causing students to be late for school.',
      priority: 'high',
      status: 'open',
      submittedDate: '2026-02-23',
      submittedBy: 'Parent - Ahmed Khan',
      studentName: 'Hassan Ahmed (Class 6)',
      responses: [],
    },
    {
      id: 5,
      complaintId: 'C-2026-005',
      driverId: 5,
      driverName: 'Sarah Johnson',
      category: 'Vehicle Maintenance',
      subject: 'AC not working',
      description: 'Van air conditioning is not functioning in hot weather.',
      priority: 'medium',
      status: 'in-progress',
      submittedDate: '2026-02-22',
      submittedBy: 'Parent - Muhammad Ali',
      studentName: 'Ali Muhammad (Class 2)',
      responses: [
        {
          date: '2026-02-22',
          message: 'AC repair scheduled for this week.',
          from: 'Driver Representative',
        },
      ],
    },
  ];

  const filteredComplaints = complaints.filter((complaint) => {
    const matchesStatus = filterStatus === 'all' || complaint.status === filterStatus;
    const matchesPriority = filterPriority === 'all' || complaint.priority === filterPriority;
    const matchesSearch =
      complaint.driverName.toLowerCase().includes(searchQuery.toLowerCase()) ||
      complaint.complaintId.includes(searchQuery) ||
      complaint.category.toLowerCase().includes(searchQuery.toLowerCase());
    return matchesStatus && matchesPriority && matchesSearch;
  });

  const selectedItem = selectedComplaint ? complaints.find((c) => c.id === selectedComplaint) : null;

  const stats = [
    {
      title: 'Open Complaints',
      value: complaints.filter((c) => c.status === 'open').length.toString(),
      icon: AlertTriangle,
      color: 'text-accent',
      bgColor: 'bg-accent-50',
    },
    {
      title: 'In Progress',
      value: complaints.filter((c) => c.status === 'in-progress').length.toString(),
      icon: Clock,
      color: 'text-highlight',
      bgColor: 'bg-highlight-50',
    },
    {
      title: 'Resolved',
      value: complaints.filter((c) => c.status === 'resolved').length.toString(),
      icon: CheckCircle,
      color: 'text-green-600',
      bgColor: 'bg-green-50',
    },
    {
      title: 'Total Complaints',
      value: complaints.length.toString(),
      icon: MessageSquare,
      color: 'text-primary',
      bgColor: 'bg-primary-50',
    },
  ];

  return (
    <div className="flex min-h-screen bg-neutral-50">
      <Sidebar userRole="school" userName={user?.name || 'School Admin'} userEmail={user?.email || 'admin@school.edu'} />

      <div className="flex-1">
        <Header title="Complaint Management" subtitle="Manage and track complaints about drivers" />

        <main className="p-4 sm:p-6">
          {/* Stats Grid */}
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4 sm:gap-6 mb-6 sm:mb-8">
            {stats.map((stat, index) => (
              <Card key={index} hover>
                <CardContent className="p-4 sm:p-6">
                  <div className="flex items-center justify-between mb-3 sm:mb-4">
                    <div className={`w-10 sm:w-12 h-10 sm:h-12 ${stat.bgColor} rounded-xl flex items-center justify-center flex-shrink-0`}>
                      <stat.icon className={`w-5 sm:w-6 h-5 sm:h-6 ${stat.color}`} />
                    </div>
                  </div>
                  <h3 className="text-xl sm:text-2xl font-bold text-neutral-900 mb-1">{stat.value}</h3>
                  <p className="text-xs sm:text-sm text-neutral-600">{stat.title}</p>
                </CardContent>
              </Card>
            ))}
          </div>

          {/* Filter Section */}
          <Card className="mb-6">
            <CardContent className="p-4 sm:p-6">
              <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
                <div>
                  <label className="block text-sm font-medium text-neutral-700 mb-2">Search</label>
                  <input
                    type="text"
                    placeholder="Search by driver, ID, or category..."
                    value={searchQuery}
                    onChange={(e) => setSearchQuery(e.target.value)}
                    className="w-full px-3 sm:px-4 py-2 border border-neutral-300 rounded-lg focus:ring-2 focus:ring-primary focus:border-transparent outline-none text-sm"
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium text-neutral-700 mb-2">Status</label>
                  <select
                    value={filterStatus}
                    onChange={(e) => setFilterStatus(e.target.value as any)}
                    className="w-full px-3 sm:px-4 py-2 border border-neutral-300 rounded-lg focus:ring-2 focus:ring-primary focus:border-transparent outline-none text-sm"
                  >
                    <option value="all">All Status</option>
                    <option value="open">Open</option>
                    <option value="in-progress">In Progress</option>
                    <option value="resolved">Resolved</option>
                  </select>
                </div>
                <div>
                  <label className="block text-sm font-medium text-neutral-700 mb-2">Priority</label>
                  <select
                    value={filterPriority}
                    onChange={(e) => setFilterPriority(e.target.value as any)}
                    className="w-full px-3 sm:px-4 py-2 border border-neutral-300 rounded-lg focus:ring-2 focus:ring-primary focus:border-transparent outline-none text-sm"
                  >
                    <option value="all">All Priorities</option>
                    <option value="high">High</option>
                    <option value="medium">Medium</option>
                    <option value="low">Low</option>
                  </select>
                </div>
              </div>
            </CardContent>
          </Card>

          <div className="grid grid-cols-1 lg:grid-cols-3 gap-4 sm:gap-6">
            {/* Complaints List */}
            <div className="lg:col-span-2">
              <Card>
                <CardHeader>
                  <CardTitle>Complaints ({filteredComplaints.length})</CardTitle>
                  <CardDescription>Click a complaint to view and respond</CardDescription>
                </CardHeader>
                <CardContent>
                  <div className="space-y-3 max-h-96 sm:max-h-none overflow-y-auto">
                    {filteredComplaints.length > 0 ? (
                      filteredComplaints.map((complaint) => (
                        <div
                          key={complaint.id}
                          onClick={() => setSelectedComplaint(complaint.id)}
                          className={`p-3 sm:p-4 border-2 rounded-lg cursor-pointer transition-all hover:shadow-md ${
                            selectedComplaint === complaint.id
                              ? 'border-primary bg-primary-50'
                              : 'border-neutral-200 bg-white hover:border-primary'
                          }`}
                        >
                          <div className="flex flex-col sm:flex-row sm:items-start sm:justify-between gap-3 sm:gap-4">
                            <div className="flex-1 min-w-0">
                              <div className="flex flex-wrap items-center gap-2 mb-2">
                                <h4 className="font-semibold text-neutral-900 text-sm">{complaint.subject}</h4>
                                <Badge variant="secondary" className="text-xs">
                                  {complaint.complaintId}
                                </Badge>
                              </div>
                              <p className="text-xs text-neutral-600 mb-2 truncate">
                                <strong>Driver:</strong> {complaint.driverName}
                              </p>
                              <div className="flex flex-wrap gap-2 text-xs">
                                <Badge
                                  variant={
                                    complaint.priority === 'high'
                                      ? 'danger'
                                      : complaint.priority === 'medium'
                                        ? 'warning'
                                        : 'secondary'
                                  }
                                >
                                  {complaint.priority}
                                </Badge>
                                <Badge
                                  variant={
                                    complaint.status === 'resolved'
                                      ? 'success'
                                      : complaint.status === 'open'
                                        ? 'danger'
                                        : 'warning'
                                  }
                                >
                                  {complaint.status}
                                </Badge>
                                <span className="text-neutral-500">{complaint.category}</span>
                              </div>
                            </div>
                            <div className="flex items-center gap-2 flex-shrink-0">
                              <span className="text-xs text-neutral-500">{complaint.responses.length} responses</span>
                              <Reply className="w-4 h-4 text-neutral-400" />
                            </div>
                          </div>
                        </div>
                      ))
                    ) : (
                      <div className="text-center py-8">
                        <MessageSquare className="w-12 h-12 text-neutral-300 mx-auto mb-2" />
                        <p className="text-neutral-600">No complaints found</p>
                      </div>
                    )}
                  </div>
                </CardContent>
              </Card>
            </div>

            {/* Detail Panel */}
            <div className="lg:col-span-1">
              {selectedItem ? (
                <Card className="sticky top-6 h-fit max-h-96 sm:max-h-none overflow-y-auto">
                  <CardHeader className="pb-3 border-b">
                    <div className="flex items-start justify-between gap-2">
                      <div>
                        <CardTitle className="text-base">{selectedItem.subject}</CardTitle>
                        <CardDescription className="text-xs">{selectedItem.complaintId}</CardDescription>
                      </div>
                      <Badge
                        variant={
                          selectedItem.priority === 'high'
                            ? 'danger'
                            : selectedItem.priority === 'medium'
                              ? 'warning'
                              : 'secondary'
                        }
                        className="text-xs flex-shrink-0"
                      >
                        {selectedItem.priority}
                      </Badge>
                    </div>
                  </CardHeader>
                  <CardContent className="space-y-4 pt-4">
                    {/* Status */}
                    <div>
                      <p className="text-xs font-semibold text-neutral-700 mb-2">Status</p>
                      <Badge
                        variant={
                          selectedItem.status === 'resolved'
                            ? 'success'
                            : selectedItem.status === 'open'
                              ? 'danger'
                              : 'warning'
                        }
                        className="w-full justify-center"
                      >
                        {selectedItem.status}
                      </Badge>
                    </div>

                    {/* Driver Info */}
                    <div className="border-t pt-4">
                      <p className="text-xs font-semibold text-neutral-700 mb-2">Driver</p>
                      <p className="text-sm font-medium text-neutral-900">{selectedItem.driverName}</p>
                      <p className="text-xs text-neutral-600 mt-1">Category: {selectedItem.category}</p>
                    </div>

                    {/* Student & Date */}
                    <div className="border-t pt-4">
                      <p className="text-xs font-semibold text-neutral-700 mb-2">Details</p>
                      <div className="space-y-2 text-xs text-neutral-600 bg-neutral-50 p-2 rounded">
                        <div>
                          <span className="font-medium">Student:</span> {selectedItem.studentName}
                        </div>
                        <div>
                          <span className="font-medium">Submitted:</span> {selectedItem.submittedDate}
                        </div>
                        <div>
                          <span className="font-medium">By:</span> {selectedItem.submittedBy}
                        </div>
                      </div>
                    </div>

                    {/* Description */}
                    <div className="border-t pt-4">
                      <p className="text-xs font-semibold text-neutral-700 mb-2">Description</p>
                      <p className="text-xs text-neutral-600 bg-neutral-50 p-2 rounded leading-relaxed">
                        {selectedItem.description}
                      </p>
                    </div>

                    {/* Response Count */}
                    <div className="border-t pt-4">
                      <p className="text-xs font-semibold text-neutral-700 mb-2">
                        Responses ({selectedItem.responses.length})
                      </p>
                      <div className="text-xs text-neutral-600">
                        {selectedItem.responses.length === 0 ? (
                          <p className="italic">No responses yet</p>
                        ) : (
                          <p>{selectedItem.responses.length} response(s) received</p>
                        )}
                      </div>
                    </div>

                    {/* Actions */}
                    <div className="border-t pt-4 flex gap-2">
                      <Button size="sm" className="flex-1 text-xs h-8" variant="secondary">
                        <Eye className="w-3 h-3 mr-1" />
                        View Full
                      </Button>
                      <Button size="sm" className="flex-1 text-xs h-8" variant="primary">
                        <Reply className="w-3 h-3 mr-1" />
                        Reply
                      </Button>
                    </div>
                  </CardContent>
                </Card>
              ) : (
                <Card>
                  <CardContent className="p-6 text-center">
                    <MessageSquare className="w-12 h-12 text-neutral-300 mx-auto mb-3" />
                    <p className="text-neutral-600 text-sm">Select a complaint to view details</p>
                  </CardContent>
                </Card>
              )}
            </div>
          </div>
        </main>
      </div>
    </div>
  );
}
