import { useContext, useState } from "react";
import { Sidebar } from "@/components/dashboard/Sidebar";
import { Header } from "@/components/dashboard/Header";
import {
  Card,
  CardHeader,
  CardTitle,
  CardDescription,
  CardContent,
} from "@/components/ui/Card";
import { Button } from "@/components/ui/Button";
import { Badge } from "@/components/ui/Badge";
import {
  Bus,
  Users,
  Clock,
  MapPin,
  Settings,
  AlertTriangle,
  TrendingUp,
  CheckCircle,
  Shield,
  Calendar,
} from "lucide-react";
// @ts-ignore: JS module without types
import userContext from "../../../context/userContext";

// @ts-ignore: JS module without types
import useActiveVans from "../../../hooks/guard/get/useActiveVans";
// @ts-ignore: JS module without types
import useRecentVerifiedStudents from "../../../hooks/guard/get/useRecentVerifiedStudents";

export default function GuardDashboard() {
  const { user, logOut }: any = useContext(userContext);
  const [selectedSchedule, setSelectedSchedule] = useState<any>(null);

  const {
    data: activeVansData,
    isLoading: activeVansLoading,
    error: activeVansError,
  } = useActiveVans();

  const {
    data: recentStudents,
    isLoading: allStudentsLoading,
    error: allStudentsError,
  } = useRecentVerifiedStudents();

  const studentsData = recentStudents?.students || [];

  // derive simple counts
  const activeVansCount =
    activeVansData?.schedule && Array.isArray(activeVansData.schedule)
      ? activeVansData.schedule.length
      : 0;
  const pendingStudentsCount = Array.isArray(studentsData)
    ? studentsData.length
    : 0;

  const stats = [
    {
      title: "Today's Vans",
      value: activeVansLoading ? "..." : activeVansCount.toString(),
      change: "+3",
      icon: Bus,
      color: "text-secondary",
      bgColor: "bg-secondary-50",
    },
    {
      title: "Pending Students",
      value: allStudentsLoading ? "..." : pendingStudentsCount.toString(),
      change: "",
      icon: Users,
      color: "text-primary",
      bgColor: "bg-primary-50",
    },
    {
      title: "Active Routes",
      value: "12",
      change: "+2",
      icon: MapPin,
      color: "text-highlight",
      bgColor: "bg-highlight-50",
    },
    {
      title: "On-Time Rate",
      value: "94%",
      change: "+1%",
      icon: TrendingUp,
      color: "text-green-600",
      bgColor: "bg-green-50",
    },
  ];

  const alerts = [
    {
      id: 1,
      type: "warning",
      title: "Late Van Arrival",
      message: "Van #A123 is running 5 minutes late",
      time: "7:40 AM",
      action: "Notify Parents",
    },
    {
      id: 2,
      type: "info",
      title: "Route Change",
      message: "Route B has been updated for today",
      time: "6:00 AM",
      action: "View Details",
    },
  ];

  return (
    <div className="flex min-h-screen bg-neutral-50">
      <Sidebar
        userRole={user?.role || "Guest"}
        userName={user?.full_name || "Zaman Ali"}
        userEmail={user?.email || "zaman.ali@example.com"}
        logOut={logOut}
      />

      <div className="flex-1">
        <Header
          title="Guard Dashboard"
          subtitle={`Welcome back, ${
            user?.full_name || "Zaman Ali"
          }! Here's what's happening today.`}
          role={user?.role}
          profile={user?.profile_photo || ""}
        />

        <main className="p-6">
          {/* Stats Grid */}
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6 mb-8">
            {stats.map((stat, index) => (
              <Card key={index} hover>
                <CardContent className="p-6">
                  <div className="flex items-center justify-between mb-4">
                    <div
                      className={`w-12 h-12 ${stat.bgColor} rounded-xl flex items-center justify-center`}
                    >
                      <stat.icon className={`w-6 h-6 ${stat.color}`} />
                    </div>
                    <Badge variant="success" className="text-xs">
                      {stat.change}
                    </Badge>
                  </div>
                  <h3 className="text-2xl font-bold text-neutral-900 mb-1">
                    {stat.value}
                  </h3>
                  <p className="text-sm text-neutral-600">{stat.title}</p>
                </CardContent>
              </Card>
            ))}
          </div>

          {/* pending students list */}
          {allStudentsError && (
            <p className="text-red-500 text-sm">
              Failed to load pending students
            </p>
          )}
          {studentsData && Array.isArray(studentsData) && (
            <Card className="mb-6">
              <CardHeader>
                <CardTitle>Students to Verify</CardTitle>
                <CardDescription>Total: {pendingStudentsCount}</CardDescription>
              </CardHeader>
              <CardContent>
                <ul className="space-y-2">
                  {studentsData.map((stu: any, idx: number) => (
                    <li
                      key={idx}
                      className="p-3 bg-neutral-50 rounded-lg flex justify-between items-center"
                    >
                      <div>
                        <p className="font-medium text-neutral-900">
                          {stu.full_name}
                        </p>
                        <p className="text-xs text-neutral-500">ID: {stu.id}</p>
                      </div>
                      <Badge variant="warning">
                        {stu.verification_time ? "Verified" : "Pending"}
                      </Badge>
                    </li>
                  ))}
                </ul>
              </CardContent>
            </Card>
          )}

          <div className="grid lg:grid-cols-3 gap-6">
            {/* Today's Schedule */}
            <div className="lg:col-span-2">
              <Card>
                <CardHeader>
                  <div className="flex items-center justify-between">
                    <div>
                      <CardTitle>Today's Schedule</CardTitle>
                      <CardDescription>
                        Van arrival and departure schedule
                      </CardDescription>
                    </div>
                    <Badge variant="primary">{activeVansCount} Routes</Badge>
                  </div>
                </CardHeader>
                <CardContent>
                  {activeVansLoading && (
                    <p className="text-neutral-500">Loading schedule...</p>
                  )}
                  {activeVansError && (
                    <p className="text-red-500 text-sm">
                      Failed to load schedule
                    </p>
                  )}
                  {activeVansData?.schedule &&
                    Array.isArray(activeVansData.schedule) && (
                      <div className="space-y-4">
                        {activeVansData.schedule.map(
                          (schedule: any, idx: number) => (
                            <div
                              key={idx}
                              className="p-4 bg-neutral-50 rounded-xl hover:bg-neutral-100 transition-colors"
                            >
                              <div className="flex items-start justify-between mb-3">
                                <div>
                                  <h4 className="font-semibold text-neutral-900 mb-1">
                                    {schedule.route_name}
                                  </h4>
                                  <p className="text-sm text-neutral-600">
                                    {schedule.start_time} - {schedule.end_time}
                                  </p>
                                </div>
                                <Badge
                                  variant={
                                    schedule.status === "Completed"
                                      ? "success"
                                      : schedule.status === "Ongoing"
                                        ? "warning"
                                        : "secondary"
                                  }
                                >
                                  {schedule.status === "Completed" ? (
                                    <CheckCircle className="w-3 h-3" />
                                  ) : null}
                                  {schedule.status}
                                </Badge>
                              </div>

                              <div className="grid grid-cols-2 gap-4 mb-3">
                                <div className="flex items-center gap-2 text-sm">
                                  <Bus className="w-4 h-4 text-neutral-500" />
                                  <span className="text-neutral-700">
                                    {schedule.total_vans} Van
                                    {schedule.total_vans !== 1 ? "s" : ""}
                                  </span>
                                </div>
                                <div className="flex items-center gap-2 text-sm">
                                  <Users className="w-4 h-4 text-neutral-500" />
                                  <span className="text-neutral-700">
                                    {schedule.total_students} Student
                                    {schedule.total_students !== 1 ? "s" : ""}
                                  </span>
                                </div>
                              </div>

                              {schedule.status !== "Completed" && (
                                <div className="flex gap-2">
                                  <Button
                                    variant="primary"
                                    size="sm"
                                    className="flex-1"
                                  >
                                    <Shield className="w-4 h-4" />
                                    Prepare for Arrival
                                  </Button>
                                  <Button 
                                    variant="outline" 
                                    size="sm"
                                    onClick={() => setSelectedSchedule(schedule)}
                                  >
                                    View Details
                                  </Button>
                                </div>
                              )}
                            </div>
                          ),
                        )}
                      </div>
                    )}
                </CardContent>
              </Card>

              {/* Student Verifications */}
              <Card className="mt-6">
                <CardHeader>
                  <CardTitle>Student Verifications</CardTitle>
                  <CardDescription>
                    Recent pickup/drop-off verifications
                  </CardDescription>
                </CardHeader>
                <CardContent>
                  {allStudentsLoading && (
                    <p className="text-neutral-500">Loading verifications...</p>
                  )}
                  {allStudentsError && (
                    <p className="text-red-500 text-sm">
                      Failed to load verifications
                    </p>
                  )}
                  {studentsData && Array.isArray(studentsData) && (
                    <div className="space-y-3">
                      {studentsData?.length > 0 ? (
                        studentsData.map((verification: any, idx: number) => (
                          <div
                            key={idx}
                            className="flex items-center justify-between p-3 bg-neutral-50 rounded-lg"
                          >
                            <div className="flex items-center gap-3">
                              <div
                                className={`w-8 h-8 rounded-lg flex items-center justify-center ${
                                  verification.verification_time
                                    ? "bg-green-100"
                                    : "bg-highlight-100"
                                }`}
                              >
                                {verification.verification_time ? (
                                  <CheckCircle className="w-4 h-4 text-green-600" />
                                ) : (
                                  <Clock className="w-4 h-4 text-highlight-600" />
                                )}
                              </div>
                              <div>
                                <p className="font-medium text-neutral-900">
                                  {verification.full_name}
                                </p>
                                <p className="text-xs text-neutral-600">
                                  ID: {verification.id}
                                </p>
                              </div>
                            </div>
                            <div className="flex items-center gap-3">
                              <span className="text-sm text-neutral-600">
                                {verification.verification_time ||
                                  "Not verified"}
                              </span>
                              <Badge
                                variant={
                                  verification.verification_time
                                    ? "success"
                                    : "warning"
                                }
                              >
                                {verification.verification_time
                                  ? "Verified"
                                  : "Pending"}
                              </Badge>
                            </div>
                          </div>
                        ))
                      ) : (
                        <p className="text-neutral-500">
                          No verifications found
                        </p>
                      )}
                    </div>
                  )}
                </CardContent>
              </Card>
            </div>

            {/* Alerts & Quick Actions */}
            <div>
              {/* Active Alerts */}
              <Card>
                <CardHeader>
                  <CardTitle>Active Alerts</CardTitle>
                  <CardDescription>
                    Notifications requiring attention
                  </CardDescription>
                </CardHeader>
                <CardContent>
                  <div className="space-y-4">
                    {alerts.map((alert) => (
                      <div
                        key={alert.id}
                        className="p-4 border border-neutral-200 rounded-lg"
                      >
                        <div className="flex items-start gap-3 mb-2">
                          <div
                            className={`w-8 h-8 rounded-lg flex items-center justify-center flex-shrink-0 ${
                              alert.type === "warning"
                                ? "bg-highlight-100"
                                : "bg-secondary-100"
                            }`}
                          >
                            {alert.type === "warning" ? (
                              <AlertTriangle className="w-4 h-4 text-highlight-600" />
                            ) : (
                              <Settings className="w-4 h-4 text-secondary-600" />
                            )}
                          </div>
                          <div className="flex-1">
                            <h4 className="font-medium text-neutral-900 text-sm">
                              {alert.title}
                            </h4>
                            <p className="text-xs text-neutral-600 mt-1">
                              {alert.message}
                            </p>
                          </div>
                        </div>
                        <Button variant="outline" size="sm" className="w-full">
                          {alert.action}
                        </Button>
                      </div>
                    ))}
                  </div>
                </CardContent>
              </Card>

              {/* Quick Actions */}
              <Card className="mt-6">
                <CardHeader>
                  <CardTitle>Quick Actions</CardTitle>
                </CardHeader>
                <CardContent>
                  <div className="space-y-2">
                    <Button variant="outline" className="w-full justify-start">
                      <Users className="w-4 h-4" />
                      Student List
                    </Button>
                    <Button variant="outline" className="w-full justify-start">
                      <Bus className="w-4 h-4" />
                      Van Tracking
                    </Button>
                    <Button variant="outline" className="w-full justify-start">
                      <Calendar className="w-4 h-4" />
                      Today's Schedule
                    </Button>
                    <Button variant="outline" className="w-full justify-start">
                      <Shield className="w-4 h-4" />
                      Emergency Protocol
                    </Button>
                  </div>
                </CardContent>
              </Card>
              {/* Performance Summary */}
              <Card className="mt-6">
                <CardHeader>
                  <CardTitle>Performance Summary</CardTitle>
                  <CardDescription>
                    Today's verification metrics
                  </CardDescription>
                </CardHeader>
                <CardContent>
                  <div className="space-y-4">
                    <div>
                      <div className="flex items-center justify-between mb-2">
                        <span className="text-sm text-neutral-600">
                          Students Verified
                        </span>
                        <span className="text-lg font-bold text-neutral-900">
                          156
                        </span>
                      </div>
                      <div className="w-full bg-neutral-200 rounded-full h-2">
                        <div
                          className="bg-green-500 h-2 rounded-full"
                          style={{ width: "85%" }}
                        />
                      </div>
                      <p className="text-xs text-neutral-500 mt-1">
                        85% of expected students
                      </p>
                    </div>

                    <div className="space-y-2">
                      <div className="flex items-center justify-between text-sm">
                        <span className="text-neutral-600">On-Time Vans</span>
                        <span className="font-semibold text-neutral-900">
                          22/24
                        </span>
                      </div>
                      <div className="flex items-center justify-between text-sm">
                        <span className="text-neutral-600">
                          Safety Incidents
                        </span>
                        <span className="font-semibold text-neutral-900">
                          0
                        </span>
                      </div>
                      <div className="flex items-center justify-between text-sm">
                        <span className="text-neutral-600">Avg. Wait Time</span>
                        <span className="font-semibold text-neutral-900">
                          2.3 min
                        </span>
                      </div>
                    </div>
                  </div>
                </CardContent>
              </Card>
            </div>
          </div>

          {/* Schedule Detail Modal */}
          {selectedSchedule && (
            <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
              <Card className="w-full max-w-2xl max-h-[90vh] overflow-y-auto">
                <CardHeader className="flex flex-row items-start justify-between">
                  <div>
                    <CardTitle>{selectedSchedule.route_name}</CardTitle>
                    <CardDescription>Route Details</CardDescription>
                  </div>
                  <button
                    onClick={() => setSelectedSchedule(null)}
                    className="text-neutral-500 hover:text-neutral-900"
                  >
                    ✕
                  </button>
                </CardHeader>
                <CardContent className="space-y-6">
                  {/* Route Info */}
                  <div className="grid grid-cols-2 gap-4">
                    <div>
                      <p className="text-sm text-neutral-600 mb-1">Route Name</p>
                      <p className="font-semibold text-neutral-900">{selectedSchedule.route_name}</p>
                    </div>
                    <div>
                      <p className="text-sm text-neutral-600 mb-1">Status</p>
                      <Badge
                        variant={
                          selectedSchedule.status === "Completed"
                            ? "success"
                            : selectedSchedule.status === "Ongoing"
                              ? "warning"
                              : "secondary"
                        }
                      >
                        {selectedSchedule.status}
                      </Badge>
                    </div>
                  </div>

                  {/* Time Info */}
                  <div className="grid grid-cols-2 gap-4">
                    <div>
                      <p className="text-sm text-neutral-600 mb-1">Start Time</p>
                      <div className="flex items-center gap-2">
                        <Clock className="w-4 h-4 text-neutral-500" />
                        <p className="font-semibold text-neutral-900">{selectedSchedule.start_time}</p>
                      </div>
                    </div>
                    <div>
                      <p className="text-sm text-neutral-600 mb-1">End Time</p>
                      <div className="flex items-center gap-2">
                        <Clock className="w-4 h-4 text-neutral-500" />
                        <p className="font-semibold text-neutral-900">{selectedSchedule.end_time}</p>
                      </div>
                    </div>
                  </div>

                  {/* Vans & Students */}
                  <div className="grid grid-cols-2 gap-4 bg-neutral-50 p-4 rounded-lg">
                    <div>
                      <p className="text-sm text-neutral-600 mb-2">Total Vans</p>
                      <div className="flex items-center gap-2">
                        <Bus className="w-5 h-5 text-secondary" />
                        <p className="text-2xl font-bold text-neutral-900">{selectedSchedule.total_vans}</p>
                      </div>
                    </div>
                    <div>
                      <p className="text-sm text-neutral-600 mb-2">Total Students</p>
                      <div className="flex items-center gap-2">
                        <Users className="w-5 h-5 text-primary" />
                        <p className="text-2xl font-bold text-neutral-900">{selectedSchedule.total_students}</p>
                      </div>
                    </div>
                  </div>

                  {/* Additional Info */}
                  {selectedSchedule.route_details && (
                    <div className="border-t pt-4">
                      <p className="text-sm text-neutral-600 mb-2">Route Details</p>
                      <p className="text-neutral-800">{selectedSchedule.route_details}</p>
                    </div>
                  )}

                  {/* Action Buttons */}
                  <div className="flex gap-3 pt-4 border-t">
                    <Button variant="primary" className="flex-1">
                      <Shield className="w-4 h-4" />
                      Prepare for Arrival
                    </Button>
                    <Button
                      variant="outline"
                      className="flex-1"
                      onClick={() => setSelectedSchedule(null)}
                    >
                      Close
                    </Button>
                  </div>
                </CardContent>
              </Card>
            </div>
          )}
        </main>
      </div>
    </div>
  );
}
