import { useContext, useState } from 'react';
import { Sidebar } from '@/components/dashboard/Sidebar';
import { Header } from '@/components/dashboard/Header';
import { Card, CardHeader, CardTitle, CardDescription, CardContent } from '@/components/ui/Card';
import { Button } from '@/components/ui/Button';
import { Badge } from '@/components/ui/Badge';
import { Avatar } from '@/components/ui/Avatar';
import {
  Navigation,
  MapPin,
  Clock,
  Play,
  Square,
  AlertTriangle,
  CheckCircle,
  Phone,
  MessageSquare,
  Compass,
} from 'lucide-react';
import userContext from "../../../context/userContext";

export default function DriverTracking() {
  const [isNavigating, setIsNavigating] = useState(false);
  const [currentStop, setCurrentStop] = useState(0);
  const { user, logOut }: any = useContext(userContext);

  const routeData = {
    name: 'Route A - Morning Pickup',
    totalStops: 8,
    completedStops: 3,
    remainingStops: 5,
    totalDistance: '15.2 km',
    coveredDistance: '6.8 km',
    estimatedArrival: '8:30 AM',
    currentSpeed: '35 km/h',
    status: 'on-route',
  };

  const stops = [
    {
      id: 1,
      order: 1,
      student: 'Sophia Davis',
      address: '789 Pine Road',
      time: '7:15 AM',
      status: 'completed',
      completedAt: '7:16 AM',
      parent: 'Emily Davis',
      phone: '+1 (555) 345-6789',
    },
    {
      id: 2,
      order: 2,
      student: 'Oliver Smith',
      address: '456 Maple Ave',
      time: '7:25 AM',
      status: 'completed',
      completedAt: '7:24 AM',
      parent: 'Michael Smith',
      phone: '+1 (555) 234-5678',
    },
    {
      id: 3,
      order: 3,
      student: 'Emma Johnson',
      address: '123 Oak Street',
      time: '7:35 AM',
      status: 'completed',
      completedAt: '7:35 AM',
      parent: 'Sarah Johnson',
      phone: '+1 (555) 123-4567',
    },
    {
      id: 4,
      order: 4,
      student: 'Liam Wilson',
      address: '321 Elm Street',
      time: '7:45 AM',
      status: 'current',
      eta: '5 mins',
      parent: 'David Wilson',
      phone: '+1 (555) 456-7890',
    },
    {
      id: 5,
      order: 5,
      student: 'Ava Martinez',
      address: '654 Birch Lane',
      time: '7:55 AM',
      status: 'upcoming',
      eta: '15 mins',
      parent: 'Maria Martinez',
      phone: '+1 (555) 567-8901',
    },
    {
      id: 6,
      order: 6,
      student: 'Noah Anderson',
      address: '987 Cedar Drive',
      time: '8:05 AM',
      status: 'upcoming',
      eta: '25 mins',
      parent: 'James Anderson',
      phone: '+1 (555) 678-9012',
    },
    {
      id: 7,
      order: 7,
      student: 'Mia Taylor',
      address: '147 Spruce Way',
      time: '8:15 AM',
      status: 'upcoming',
      eta: '35 mins',
      parent: 'Lisa Taylor',
      phone: '+1 (555) 789-0123',
    },
    {
      id: 8,
      order: 8,
      student: 'School Drop-off',
      address: 'Lincoln Elementary',
      time: '8:30 AM',
      status: 'upcoming',
      eta: '50 mins',
      isDestination: true,
    },
  ];

  const currentStopData = stops.find(s => s.status === 'current');

  return (
    <div className="flex min-h-screen bg-neutral-50">
      <Sidebar
        userRole={user?.role || "Guest"}
        userName={user?.full_name || "Zaman Ali"}
        userEmail={user?.email || "zaman.ali@example.com"}
        logOut={logOut}
      />

      <div className="flex-1">
        <Header title="Live Navigation" subtitle="Real-time route tracking and navigation" role={user?.role}
          profile={user?.profile_photo || ""}/>

        <main className="p-6">
          {/* Status Banner */}
          <Card className={`mb-6 ${isNavigating ? 'bg-gradient-to-br from-green-500 to-green-600' : 'bg-gradient-to-br from-primary to-secondary'} text-white`}>
            <CardContent className="p-6">
              <div className="flex items-center justify-between">
                <div className="flex-1">
                  <div className="flex items-center gap-3 mb-2">
                    <h2 className="text-2xl font-bold">{routeData.name}</h2>
                    <Badge variant={isNavigating ? 'success' : 'secondary'} className="bg-white/20 text-white border-0">
                      <span className={`status-dot ${isNavigating ? 'status-active' : 'status-inactive'} animate-pulse`} />
                      {isNavigating ? 'Navigating' : 'Ready to Start'}
                    </Badge>
                  </div>
                  <p className="text-white/90">
                    Stop {routeData.completedStops + 1} of {routeData.totalStops} •
                    {isNavigating ? ` ${routeData.remainingStops} stops remaining` : ' Not started'}
                  </p>
                </div>
                <div className="flex gap-3">
                  <Button
                    variant={isNavigating ? 'accent' : 'secondary'}
                    size="lg"
                    onClick={() => setIsNavigating(!isNavigating)}
                    className="bg-white text-primary hover:bg-neutral-100"
                  >
                    {isNavigating ? (
                      <>
                        <Square className="w-5 h-5" />
                        End Route
                      </>
                    ) : (
                      <>
                        <Play className="w-5 h-5" />
                        Start Navigation
                      </>
                    )}
                  </Button>
                  {isNavigating && (
                    <Button
                      variant="outline"
                      size="lg"
                      className="border-2 border-white text-white hover:bg-white/10"
                    >
                      <AlertTriangle className="w-5 h-5" />
                      Report Delay
                    </Button>
                  )}
                </div>
              </div>
            </CardContent>
          </Card>

          <div className="grid lg:grid-cols-3 gap-6">
            {/* Map and Current Stop */}
            <div className="lg:col-span-2 space-y-6">
              {/* Live Map */}
              <Card>
                <CardHeader>
                  <div className="flex items-center justify-between">
                    <CardTitle>Live Map</CardTitle>
                    <div className="flex items-center gap-2">
                      <Badge variant="success" className="flex items-center gap-1">
                        <span className="status-dot status-active animate-pulse" />
                        Live
                      </Badge>
                      <Badge variant="secondary">
                        <Compass className="w-3 h-3" />
                        {routeData.currentSpeed}
                      </Badge>
                    </div>
                  </div>
                </CardHeader>
                <CardContent>
                  {/* Map Placeholder */}
                  <div className="relative w-full h-96 bg-neutral-100 rounded-xl overflow-hidden">
                    <div className="absolute inset-0 flex items-center justify-center">
                      <div className="text-center">
                        <Navigation className="w-16 h-16 text-primary mx-auto mb-2" />
                        <p className="text-sm text-neutral-600">Google Maps Integration</p>
                        <p className="text-xs text-neutral-500">Real-time GPS tracking</p>
                      </div>
                    </div>

                    {/* Floating Stats */}
                    <div className="absolute top-4 left-4 right-4 grid grid-cols-3 gap-3">
                      <div className="bg-white rounded-lg shadow-card p-3">
                        <p className="text-xs text-neutral-600">Distance</p>
                        <p className="text-sm font-bold text-neutral-900">
                          {routeData.coveredDistance} / {routeData.totalDistance}
                        </p>
                      </div>
                      <div className="bg-white rounded-lg shadow-card p-3">
                        <p className="text-xs text-neutral-600">ETA</p>
                        <p className="text-sm font-bold text-neutral-900">{routeData.estimatedArrival}</p>
                      </div>
                      <div className="bg-white rounded-lg shadow-card p-3">
                        <p className="text-xs text-neutral-600">Speed</p>
                        <p className="text-sm font-bold text-neutral-900">{routeData.currentSpeed}</p>
                      </div>
                    </div>
                  </div>
                </CardContent>
              </Card>

              {/* Current Stop Details */}
              {currentStopData && isNavigating && (
                <Card className="border-2 border-primary">
                  <CardHeader>
                    <div className="flex items-center justify-between">
                      <div>
                        <CardTitle className="flex items-center gap-2">
                          <MapPin className="w-5 h-5 text-primary" />
                          Next Stop
                        </CardTitle>
                        <CardDescription>Arriving in {currentStopData.eta}</CardDescription>
                      </div>
                      <Badge variant="warning" className="text-lg px-4 py-2">
                        Stop {currentStopData.order}
                      </Badge>
                    </div>
                  </CardHeader>
                  <CardContent>
                    <div className="flex items-start gap-4 mb-4">
                      <Avatar name={currentStopData.student} size="xl" />
                      <div className="flex-1">
                        <h3 className="text-xl font-bold text-neutral-900 mb-1">
                          {currentStopData.student}
                        </h3>
                        <p className="text-neutral-600 mb-2">{currentStopData.address}</p>
                        <div className="flex items-center gap-4 text-sm">
                          <div className="flex items-center gap-2 text-neutral-600">
                            <Clock className="w-4 h-4" />
                            <span>Scheduled: {currentStopData.time}</span>
                          </div>
                          <div className="flex items-center gap-2 text-primary font-semibold">
                            <Navigation className="w-4 h-4" />
                            <span>ETA: {currentStopData.eta}</span>
                          </div>
                        </div>
                      </div>
                    </div>

                    <div className="p-4 bg-secondary-50 rounded-lg mb-4">
                      <p className="text-sm font-medium text-neutral-900 mb-2">Parent Contact</p>
                      <p className="text-sm text-neutral-700">{currentStopData.parent}</p>
                      <p className="text-sm text-neutral-600">{currentStopData.phone}</p>
                    </div>

                    <div className="flex gap-2">
                      <Button variant="primary" className="flex-1">
                        <CheckCircle className="w-4 h-4" />
                        Mark as Picked Up
                      </Button>
                      <Button variant="outline">
                        <Phone className="w-4 h-4" />
                        Call Parent
                      </Button>
                      <Button variant="outline">
                        <MessageSquare className="w-4 h-4" />
                      </Button>
                    </div>
                  </CardContent>
                </Card>
              )}
            </div>

            {/* Route Progress */}
            <div>
              <Card>
                <CardHeader>
                  <CardTitle>Route Progress</CardTitle>
                  <CardDescription>
                    {routeData.completedStops} of {routeData.totalStops} stops completed
                  </CardDescription>
                </CardHeader>
                <CardContent>
                  {/* Progress Bar */}
                  <div className="mb-6">
                    <div className="flex items-center justify-between text-sm mb-2">
                      <span className="text-neutral-600">Progress</span>
                      <span className="font-semibold text-neutral-900">
                        {Math.round((routeData.completedStops / routeData.totalStops) * 100)}%
                      </span>
                    </div>
                    <div className="w-full bg-neutral-200 rounded-full h-3">
                      <div
                        className="bg-gradient-to-r from-primary to-secondary h-3 rounded-full transition-all duration-500"
                        style={{ width: `${(routeData.completedStops / routeData.totalStops) * 100}%` }}
                      />
                    </div>
                  </div>

                  {/* Stops List */}
                  <div className="space-y-3 max-h-[600px] overflow-y-auto scrollbar-hide">
                    {stops.map((stop, index) => (
                      <div
                        key={stop.id}
                        className={`p-3 rounded-lg border-2 transition-all ${
                          stop.status === 'current'
                            ? 'border-primary bg-primary-50'
                            : stop.status === 'completed'
                            ? 'border-green-200 bg-green-50'
                            : 'border-neutral-200 bg-white'
                        }`}
                      >
                        <div className="flex items-start gap-3">
                          <div
                            className={`w-8 h-8 rounded-full flex items-center justify-center text-xs font-bold flex-shrink-0 ${
                              stop.status === 'completed'
                                ? 'bg-green-500 text-white'
                                : stop.status === 'current'
                                ? 'bg-primary text-white'
                                : 'bg-neutral-200 text-neutral-600'
                            }`}
                          >
                            {stop.status === 'completed' ? (
                              <CheckCircle className="w-4 h-4" />
                            ) : (
                              stop.order
                            )}
                          </div>

                          <div className="flex-1 min-w-0">
                            <div className="flex items-start justify-between mb-1">
                              <p className="font-semibold text-neutral-900 text-sm">
                                {stop.student}
                              </p>
                              {stop.status === 'completed' && (
                                <Badge variant="success" className="text-xs">
                                  Done
                                </Badge>
                              )}
                              {stop.status === 'current' && (
                                <Badge variant="warning" className="text-xs">
                                  Current
                                </Badge>
                              )}
                            </div>
                            <p className="text-xs text-neutral-600 mb-1">{stop.address}</p>
                            <div className="flex items-center gap-2 text-xs text-neutral-500">
                              <Clock className="w-3 h-3" />
                              {stop.status === 'completed' ? (
                                <span>Completed at {stop.completedAt}</span>
                              ) : stop.status === 'current' ? (
                                <span className="text-primary font-semibold">ETA: {stop.eta}</span>
                              ) : (
                                <span>{stop.time}</span>
                              )}
                            </div>
                          </div>
                        </div>
                      </div>
                    ))}
                  </div>
                </CardContent>
              </Card>
            </div>
          </div>
        </main>
      </div>
    </div>
  );
}
