import { useContext, useState } from "react";
import { Sidebar } from "@/components/dashboard/Sidebar";
import { Header } from "@/components/dashboard/Header";
import {
  Card,
  CardContent,
} from "@/components/ui/Card";
import { Button } from "@/components/ui/Button";
import { Badge } from "@/components/ui/Badge";
import {
  AlertTriangle,
  Bell,
  CheckCircle,
  Clock,
  Car,
  Users,
  Eye,
  Trash2,
} from "lucide-react";
import userContext from "../../../context/userContext";

export default function GuardAlerts() {
  const [filterType, setFilterType] = useState("all");
  const { user, logOut }: any = useContext(userContext);

  const stats = [
    {
      title: "Total Alerts",
      value: "12",
      subtitle: "Today",
      icon: Bell,
      color: "text-primary",
      bgColor: "bg-primary-50",
    },
    {
      title: "Critical",
      value: "2",
      subtitle: "Urgent",
      icon: AlertTriangle,
      color: "text-accent",
      bgColor: "bg-accent-50",
    },
    {
      title: "Resolved",
      value: "8",
      subtitle: "Handled",
      icon: CheckCircle,
      color: "text-green-600",
      bgColor: "bg-green-50",
    },
    {
      title: "Pending",
      value: "4",
      subtitle: "Awaiting action",
      icon: Clock,
      color: "text-highlight",
      bgColor: "bg-highlight-50",
    },
  ];

  const alerts = [
    {
      id: 1,
      type: "delay",
      severity: "high",
      title: "Van #H234 Delayed",
      message:
        "Van #H234 is running 15 minutes late due to traffic jam on Main Street",
      van: "Van #H234",
      driver: "James Taylor",
      time: "5 mins ago",
      status: "active",
      affectedStudents: 13,
    },
    {
      id: 2,
      type: "delay",
      severity: "medium",
      title: "Van #D012 Approaching Late",
      message: "Van #D012 is expected to arrive 5 minutes late",
      van: "Van #D012",
      driver: "Robert Lee",
      time: "10 mins ago",
      status: "active",
      affectedStudents: 14,
    },
    {
      id: 3,
      type: "missing",
      severity: "high",
      title: "Student Not on Van",
      message:
        "Student Emma Johnson was not found on Van #A123 during verification",
      van: "Van #A123",
      driver: "John Smith",
      time: "15 mins ago",
      status: "resolved",
      affectedStudents: 1,
    },
    {
      id: 4,
      type: "early",
      severity: "low",
      title: "Van #A123 Arrived Early",
      message: "Van #A123 arrived 5 minutes earlier than scheduled",
      van: "Van #A123",
      driver: "John Smith",
      time: "1 hour ago",
      status: "resolved",
      affectedStudents: 12,
    },
    {
      id: 5,
      type: "breakdown",
      severity: "high",
      title: "Vehicle Issue Reported",
      message:
        "Van #C789 reported a minor mechanical issue, backup van dispatched",
      van: "Van #C789",
      driver: "Michael Brown",
      time: "2 hours ago",
      status: "resolved",
      affectedStudents: 8,
    },
    {
      id: 6,
      type: "weather",
      severity: "medium",
      title: "Weather Alert",
      message: "Heavy rain expected, all vans advised to drive carefully",
      van: "All Vans",
      driver: "All Drivers",
      time: "3 hours ago",
      status: "active",
      affectedStudents: 96,
    },
  ];

  const filteredAlerts =
    filterType === "all"
      ? alerts
      : alerts.filter((a) => a.status === filterType);

  const getSeverityBadge = (severity: string) => {
    switch (severity) {
      case "high":
        return <Badge variant="danger">High</Badge>;
      case "medium":
        return <Badge variant="warning">Medium</Badge>;
      case "low":
        return <Badge variant="secondary">Low</Badge>;
      default:
        return null;
    }
  };

  const getStatusBadge = (status: string) => {
    switch (status) {
      case "active":
        return (
          <Badge variant="warning">
            <Clock className="w-3 h-3" />
            Active
          </Badge>
        );
      case "resolved":
        return (
          <Badge variant="success">
            <CheckCircle className="w-3 h-3" />
            Resolved
          </Badge>
        );
      default:
        return null;
    }
  };

  const getAlertIcon = (type: string) => {
    switch (type) {
      case "delay":
        return <Clock className="w-5 h-5" />;
      case "missing":
        return <Users className="w-5 h-5" />;
      case "breakdown":
        return <Car className="w-5 h-5" />;
      case "weather":
        return <AlertTriangle className="w-5 h-5" />;
      default:
        return <Bell className="w-5 h-5" />;
    }
  };

  return (
    <div className="flex min-h-screen bg-neutral-50">
      <Sidebar
        userRole={user?.role || "Guest"}
        userName={user?.full_name || "Zaman Ali"}
        userEmail={user?.email || "zaman.ali@example.com"}
        logOut={logOut}
      />

      <div className="flex-1">
        <Header
          title="Alerts & Notifications"
          subtitle="Monitor and manage system alerts"
          role={user?.role}
          profile={user?.profile_photo || ""}
        />

        <main className="p-6">
          {/* Stats Grid */}
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6 mb-8">
            {stats.map((stat, index) => (
              <Card key={index} hover>
                <CardContent className="p-6">
                  <div className="flex items-center justify-between mb-4">
                    <div
                      className={`w-12 h-12 ${stat.bgColor} rounded-xl flex items-center justify-center`}
                    >
                      <stat.icon className={`w-6 h-6 ${stat.color}`} />
                    </div>
                  </div>
                  <h3 className="text-2xl font-bold text-neutral-900 mb-1">
                    {stat.value}
                  </h3>
                  <p className="text-sm text-neutral-600">{stat.title}</p>
                  <p className="text-xs text-neutral-500">{stat.subtitle}</p>
                </CardContent>
              </Card>
            ))}
          </div>

          {/* Filters */}
          <Card className="mb-6">
            <CardContent className="p-4">
              <div className="flex gap-2">
                <Button
                  variant={filterType === "all" ? "primary" : "outline"}
                  size="sm"
                  onClick={() => setFilterType("all")}
                >
                  All Alerts
                </Button>
                <Button
                  variant={filterType === "active" ? "primary" : "outline"}
                  size="sm"
                  onClick={() => setFilterType("active")}
                >
                  <Clock className="w-4 h-4" />
                  Active
                </Button>
                <Button
                  variant={filterType === "resolved" ? "primary" : "outline"}
                  size="sm"
                  onClick={() => setFilterType("resolved")}
                >
                  <CheckCircle className="w-4 h-4" />
                  Resolved
                </Button>
              </div>
            </CardContent>
          </Card>

          {/* Alerts List */}
          <div className="space-y-4">
            {filteredAlerts.map((alert) => (
              <Card
                key={alert.id}
                hover
                className={`${
                  alert.severity === "high" && alert.status === "active"
                    ? "border-2 border-accent"
                    : ""
                }`}
              >
                <CardContent className="p-6">
                  <div className="flex items-start gap-4">
                    {/* Icon */}
                    <div
                      className={`w-12 h-12 rounded-xl flex items-center justify-center flex-shrink-0 ${
                        alert.severity === "high"
                          ? "bg-accent-100 text-accent"
                          : alert.severity === "medium"
                            ? "bg-highlight-100 text-highlight"
                            : "bg-secondary-100 text-secondary"
                      }`}
                    >
                      {getAlertIcon(alert.type)}
                    </div>

                    {/* Content */}
                    <div className="flex-1">
                      <div className="flex items-start justify-between mb-2">
                        <div>
                          <div className="flex items-center gap-3 mb-1">
                            <h3 className="text-lg font-bold text-neutral-900">
                              {alert.title}
                            </h3>
                            {getSeverityBadge(alert.severity)}
                            {getStatusBadge(alert.status)}
                          </div>
                          <p className="text-sm text-neutral-600">
                            {alert.time}
                          </p>
                        </div>
                      </div>

                      <p className="text-neutral-700 mb-4">{alert.message}</p>

                      <div className="grid md:grid-cols-3 gap-4 mb-4">
                        <div className="flex items-center gap-2 p-3 bg-neutral-50 rounded-lg">
                          <Car className="w-4 h-4 text-neutral-500" />
                          <div>
                            <p className="text-xs text-neutral-600">Van</p>
                            <p className="text-sm font-semibold text-neutral-900">
                              {alert.van}
                            </p>
                          </div>
                        </div>

                        <div className="flex items-center gap-2 p-3 bg-neutral-50 rounded-lg">
                          <Users className="w-4 h-4 text-neutral-500" />
                          <div>
                            <p className="text-xs text-neutral-600">Driver</p>
                            <p className="text-sm font-semibold text-neutral-900">
                              {alert.driver}
                            </p>
                          </div>
                        </div>

                        <div className="flex items-center gap-2 p-3 bg-neutral-50 rounded-lg">
                          <AlertTriangle className="w-4 h-4 text-neutral-500" />
                          <div>
                            <p className="text-xs text-neutral-600">Affected</p>
                            <p className="text-sm font-semibold text-neutral-900">
                              {alert.affectedStudents} student
                              {alert.affectedStudents !== 1 ? "s" : ""}
                            </p>
                          </div>
                        </div>
                      </div>

                      <div className="flex gap-2">
                        {alert.status === "active" && (
                          <Button variant="primary" size="sm">
                            <CheckCircle className="w-4 h-4" />
                            Mark as Resolved
                          </Button>
                        )}
                        <Button variant="outline" size="sm">
                          <Eye className="w-4 h-4" />
                          View Details
                        </Button>
                        <Button
                          variant="ghost"
                          size="sm"
                          className="text-accent hover:bg-accent-50"
                        >
                          <Trash2 className="w-4 h-4" />
                        </Button>
                      </div>
                    </div>
                  </div>
                </CardContent>
              </Card>
            ))}
          </div>

          {/* Empty State */}
          {filteredAlerts.length === 0 && (
            <Card>
              <CardContent className="p-12 text-center">
                <Bell className="w-16 h-16 text-neutral-300 mx-auto mb-4" />
                <h3 className="text-xl font-semibold text-neutral-900 mb-2">
                  No alerts found
                </h3>
                <p className="text-neutral-600">
                  {filterType === "all"
                    ? "No alerts to display"
                    : `No ${filterType} alerts at this time`}
                </p>
              </CardContent>
            </Card>
          )}
        </main>
      </div>
    </div>
  );
}
