import { useContext } from "react";
import { Sidebar } from "@/components/dashboard/Sidebar";
import { Header } from "@/components/dashboard/Header";
import {
  Card,
  CardContent,
} from "@/components/ui/Card";
import { Button } from "@/components/ui/Button";
import { Badge } from "@/components/ui/Badge";
import { Avatar } from "@/components/ui/Avatar";
import {
  Car,
  MapPin,
  Clock,
  Users,
  CheckCircle,
  AlertTriangle,
  Eye,
  Navigation,
  UserCheck,
  Phone,
} from "lucide-react";
import userContext from "../../../context/userContext";

export default function GuardVans() {
  const { user, logOut }: any = useContext(userContext);
  const stats = [
    {
      title: "Expected Vans",
      value: "8",
      subtitle: "Today",
      icon: Car,
      color: "text-primary",
      bgColor: "bg-primary-50",
    },
    {
      title: "Arrived",
      value: "3",
      subtitle: "On campus",
      icon: CheckCircle,
      color: "text-green-600",
      bgColor: "bg-green-50",
    },
    {
      title: "En Route",
      value: "4",
      subtitle: "Approaching",
      icon: Navigation,
      color: "text-secondary",
      bgColor: "bg-secondary-50",
    },
    {
      title: "Delayed",
      value: "1",
      subtitle: "Running late",
      icon: AlertTriangle,
      color: "text-accent",
      bgColor: "bg-accent-50",
    },
  ];

  const vans = [
    {
      id: 1,
      vanNumber: "Van #A123",
      driver: "John Smith",
      driverPhone: "+1 (555) 234-5678",
      route: "Route A - Morning",
      expectedTime: "7:45 AM",
      actualTime: "7:46 AM",
      status: "arrived",
      students: 12,
      verified: 12,
      eta: "Arrived",
      location: "School Parking Lot",
    },
    {
      id: 2,
      vanNumber: "Van #B456",
      driver: "Sarah Williams",
      driverPhone: "+1 (555) 789-0123",
      route: "Route B - Morning",
      expectedTime: "7:50 AM",
      actualTime: "7:50 AM",
      status: "arrived",
      students: 10,
      verified: 10,
      eta: "Arrived",
      location: "School Parking Lot",
    },
    {
      id: 3,
      vanNumber: "Van #C789",
      driver: "Michael Brown",
      driverPhone: "+1 (555) 345-6789",
      route: "Route C - Morning",
      expectedTime: "7:55 AM",
      actualTime: "7:55 AM",
      status: "arrived",
      students: 8,
      verified: 8,
      eta: "Arrived",
      location: "School Parking Lot",
    },
    {
      id: 4,
      vanNumber: "Van #D012",
      driver: "Robert Lee",
      driverPhone: "+1 (555) 456-7890",
      route: "Route D - Morning",
      expectedTime: "8:00 AM",
      actualTime: null,
      status: "approaching",
      students: 14,
      verified: 0,
      eta: "3 mins",
      location: "0.5 km away",
    },
    {
      id: 5,
      vanNumber: "Van #E345",
      driver: "Emily Davis",
      driverPhone: "+1 (555) 567-8901",
      route: "Route E - Morning",
      expectedTime: "8:05 AM",
      actualTime: null,
      status: "en-route",
      students: 9,
      verified: 0,
      eta: "8 mins",
      location: "2.1 km away",
    },
    {
      id: 6,
      vanNumber: "Van #F678",
      driver: "David Wilson",
      driverPhone: "+1 (555) 678-9012",
      route: "Route F - Morning",
      expectedTime: "8:10 AM",
      actualTime: null,
      status: "en-route",
      students: 11,
      verified: 0,
      eta: "13 mins",
      location: "3.8 km away",
    },
    {
      id: 7,
      vanNumber: "Van #G901",
      driver: "Lisa Anderson",
      driverPhone: "+1 (555) 789-0123",
      route: "Route G - Morning",
      expectedTime: "8:15 AM",
      actualTime: null,
      status: "en-route",
      students: 7,
      verified: 0,
      eta: "18 mins",
      location: "5.2 km away",
    },
    {
      id: 8,
      vanNumber: "Van #H234",
      driver: "James Taylor",
      driverPhone: "+1 (555) 890-1234",
      route: "Route H - Morning",
      expectedTime: "8:00 AM",
      actualTime: null,
      status: "delayed",
      students: 13,
      verified: 0,
      eta: "15 mins",
      location: "4.5 km away",
      delayReason: "Traffic jam on Main Street",
    },
  ];

  const getStatusBadge = (status: string) => {
    switch (status) {
      case "arrived":
        return (
          <Badge variant="success">
            <CheckCircle className="w-3 h-3" />
            Arrived
          </Badge>
        );
      case "approaching":
        return (
          <Badge variant="warning">
            <Clock className="w-3 h-3" />
            Approaching
          </Badge>
        );
      case "en-route":
        return (
          <Badge variant="secondary">
            <Navigation className="w-3 h-3" />
            En Route
          </Badge>
        );
      case "delayed":
        return (
          <Badge variant="danger">
            <AlertTriangle className="w-3 h-3" />
            Delayed
          </Badge>
        );
      default:
        return null;
    }
  };

  return (
    <div className="flex min-h-screen bg-neutral-50">
      <Sidebar
        userRole={user?.role || "Guest"}
        userName={user?.full_name || "Zaman Ali"}
        userEmail={user?.email || "zaman.ali@example.com"}
        logOut={logOut}
      />

      <div className="flex-1">
        <Header
          title="Van Monitoring"
          subtitle="Track incoming vans and student arrivals"
          role={user?.role}
          profile={user?.profile_photo || ""}
        />

        <main className="p-6">
          {/* Stats Grid */}
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6 mb-8">
            {stats.map((stat, index) => (
              <Card key={index} hover>
                <CardContent className="p-6">
                  <div className="flex items-center justify-between mb-4">
                    <div
                      className={`w-12 h-12 ${stat.bgColor} rounded-xl flex items-center justify-center`}
                    >
                      <stat.icon className={`w-6 h-6 ${stat.color}`} />
                    </div>
                  </div>
                  <h3 className="text-2xl font-bold text-neutral-900 mb-1">
                    {stat.value}
                  </h3>
                  <p className="text-sm text-neutral-600">{stat.title}</p>
                  <p className="text-xs text-neutral-500">{stat.subtitle}</p>
                </CardContent>
              </Card>
            ))}
          </div>

          {/* Vans List */}
          <div className="space-y-4">
            {vans.map((van) => (
              <Card
                key={van.id}
                hover
                className={
                  van.status === "delayed" ? "border-2 border-accent" : ""
                }
              >
                <CardContent className="p-6">
                  <div className="flex flex-col lg:flex-row gap-6">
                    {/* Left Section */}
                    <div className="flex-1">
                      <div className="flex items-start justify-between mb-4">
                        <div>
                          <div className="flex items-center gap-3 mb-2">
                            <h3 className="text-xl font-bold text-neutral-900">
                              {van.vanNumber}
                            </h3>
                            {getStatusBadge(van.status)}
                          </div>
                          <p className="text-sm text-neutral-600">
                            {van.route}
                          </p>
                        </div>
                        <div className="text-right">
                          <p className="text-sm text-neutral-600">Expected</p>
                          <p className="text-lg font-bold text-neutral-900">
                            {van.expectedTime}
                          </p>
                          {van.actualTime && (
                            <p className="text-xs text-green-600">
                              Arrived: {van.actualTime}
                            </p>
                          )}
                        </div>
                      </div>

                      {/* Van Details Grid */}
                      <div className="grid md:grid-cols-4 gap-4 mb-4">
                        <div className="p-3 bg-neutral-50 rounded-lg">
                          <div className="flex items-center gap-2 mb-1">
                            <Users className="w-4 h-4 text-neutral-500" />
                            <span className="text-xs text-neutral-600">
                              Students
                            </span>
                          </div>
                          <p className="text-sm font-semibold text-neutral-900">
                            {van.verified}/{van.students}
                          </p>
                          {van.status === "arrived" && (
                            <div className="w-full bg-neutral-200 rounded-full h-1.5 mt-2">
                              <div
                                className={`h-1.5 rounded-full ${
                                  van.verified === van.students
                                    ? "bg-green-500"
                                    : "bg-primary"
                                }`}
                                style={{
                                  width: `${(van.verified / van.students) * 100}%`,
                                }}
                              />
                            </div>
                          )}
                        </div>

                        <div className="p-3 bg-neutral-50 rounded-lg">
                          <div className="flex items-center gap-2 mb-1">
                            <Clock className="w-4 h-4 text-neutral-500" />
                            <span className="text-xs text-neutral-600">
                              ETA
                            </span>
                          </div>
                          <p className="text-sm font-semibold text-neutral-900">
                            {van.eta}
                          </p>
                        </div>

                        <div className="p-3 bg-neutral-50 rounded-lg">
                          <div className="flex items-center gap-2 mb-1">
                            <MapPin className="w-4 h-4 text-neutral-500" />
                            <span className="text-xs text-neutral-600">
                              Location
                            </span>
                          </div>
                          <p className="text-sm font-semibold text-neutral-900">
                            {van.location}
                          </p>
                        </div>

                        <div className="p-3 bg-neutral-50 rounded-lg">
                          <div className="flex items-center gap-2 mb-1">
                            <UserCheck className="w-4 h-4 text-neutral-500" />
                            <span className="text-xs text-neutral-600">
                              Driver
                            </span>
                          </div>
                          <p className="text-sm font-semibold text-neutral-900">
                            {van.driver}
                          </p>
                        </div>
                      </div>

                      {/* Driver Contact */}
                      <div className="flex items-center gap-3 p-3 bg-secondary-50 rounded-lg">
                        <Avatar name={van.driver} size="md" />
                        <div className="flex-1">
                          <p className="text-sm font-semibold text-neutral-900">
                            {van.driver}
                          </p>
                          <p className="text-xs text-neutral-600">
                            {van.driverPhone}
                          </p>
                        </div>
                        <Button variant="outline" size="sm">
                          <Phone className="w-4 h-4" />
                          Call
                        </Button>
                      </div>

                      {/* Delay Alert */}
                      {van.status === "delayed" && van.delayReason && (
                        <div className="mt-4 p-3 bg-accent-50 rounded-lg border border-accent-200">
                          <div className="flex items-start gap-2">
                            <AlertTriangle className="w-5 h-5 text-accent flex-shrink-0 mt-0.5" />
                            <div>
                              <p className="text-sm font-medium text-neutral-900">
                                Delay Reported
                              </p>
                              <p className="text-sm text-neutral-700">
                                {van.delayReason}
                              </p>
                            </div>
                          </div>
                        </div>
                      )}
                    </div>

                    {/* Right Section - Actions */}
                    <div className="lg:w-48 flex flex-col gap-2">
                      {van.status === "arrived" &&
                        van.verified < van.students && (
                          <Button
                            variant="primary"
                            size="sm"
                            className="w-full"
                          >
                            <UserCheck className="w-4 h-4" />
                            Verify Students
                          </Button>
                        )}

                      {van.status === "arrived" &&
                        van.verified === van.students && (
                          <Button
                            variant="outline"
                            size="sm"
                            className="w-full text-green-600 hover:bg-green-50"
                          >
                            <CheckCircle className="w-4 h-4" />
                            Complete
                          </Button>
                        )}

                      <Button variant="outline" size="sm" className="w-full">
                        <Eye className="w-4 h-4" />
                        View Details
                      </Button>

                      <Button variant="outline" size="sm" className="w-full">
                        <MapPin className="w-4 h-4" />
                        Track Location
                      </Button>

                      {van.status === "approaching" && (
                        <Badge
                          variant="warning"
                          className="w-full justify-center py-2"
                        >
                          <Clock className="w-3 h-3" />
                          Arriving Soon
                        </Badge>
                      )}
                    </div>
                  </div>
                </CardContent>
              </Card>
            ))}
          </div>
        </main>
      </div>
    </div>
  );
}
