import React, { useContext, useState } from "react";
import { Sidebar } from "@/components/dashboard/Sidebar";
import { Header } from "@/components/dashboard/Header";
import {
  Card,
  CardHeader,
  CardTitle,
  CardDescription,
  CardContent,
} from "@/components/ui/Card";
import { Button } from "@/components/ui/Button";
import { Badge } from "@/components/ui/Badge";
import { Avatar } from "@/components/ui/Avatar";
import {
  MapPin,
  Navigation,
  Clock,
  Phone,
  MessageSquare,
  AlertCircle,
  CheckCircle,
  Star,
} from "lucide-react";
import userContext from "../../../context/userContext";

export default function ParentTrack() {
  const [selectedChild, setSelectedChild] = useState(0);
   const { user, logOut }: any = useContext(userContext);

  const children = [
    {
      id: 1,
      name: "Emma Johnson",
      vanNumber: "Van #A123",
      driver: "John Smith",
      driverPhone: "+1 (555) 123-4567",
      driverRating: 4.8,
      currentLocation: "Main Street & 5th Avenue",
      nextStop: "123 Oak Street",
      eta: "8 mins",
      distance: "2.3 km",
      status: "on-route",
      stops: [
        {
          location: "789 Pine Road",
          student: "Sophia Davis",
          status: "completed",
          time: "7:35 AM",
        },
        {
          location: "456 Maple Ave",
          student: "Oliver Smith",
          status: "completed",
          time: "7:25 AM",
        },
        {
          location: "123 Oak Street",
          student: "Emma Johnson",
          status: "upcoming",
          time: "7:45 AM",
        },
        {
          location: "Lincoln Elementary",
          student: "School",
          status: "pending",
          time: "8:00 AM",
        },
      ],
    },
    {
      id: 2,
      name: "Oliver Johnson",
      vanNumber: "Van #A123",
      driver: "John Smith",
      driverPhone: "+1 (555) 123-4567",
      driverRating: 4.8,
      currentLocation: "Main Street & 5th Avenue",
      nextStop: "123 Oak Street",
      eta: "8 mins",
      distance: "2.3 km",
      status: "on-route",
      stops: [
        {
          location: "789 Pine Road",
          student: "Sophia Davis",
          status: "completed",
          time: "7:35 AM",
        },
        {
          location: "456 Maple Ave",
          student: "Oliver Smith",
          status: "completed",
          time: "7:25 AM",
        },
        {
          location: "123 Oak Street",
          student: "Emma Johnson",
          status: "upcoming",
          time: "7:45 AM",
        },
        {
          location: "Lincoln Elementary",
          student: "School",
          status: "pending",
          time: "8:00 AM",
        },
      ],
    },
  ];

  const child = children[selectedChild];

  return (
    <div className="flex min-h-screen bg-neutral-50">
      <Sidebar
        userRole={user?.role || "Guest"}
        userName={user?.full_name || "Zaman Ali"}
        userEmail={user?.email || "zaman.ali@example.com"}
        logOut={logOut}
      />

      <div className="flex-1">
        <Header
          title={`${user?.role ? user.role.split(" ")[0] : "Guest"} DASHBOARD`}
          subtitle={`Welcome back, ${
            user?.full_name || "Zaman Ali"
          }! Here's what's happening today.`}
          role={user?.role}
          profile={user?.profile_photo || ""}
        />

        <main className="p-6">
          {/* Child Selector */}
          <div className="mb-6 flex gap-3 overflow-x-auto pb-2">
            {children.map((c, index) => (
              <button
                key={c.id}
                onClick={() => setSelectedChild(index)}
                className={`flex items-center gap-3 px-4 py-3 rounded-xl border-2 transition-all whitespace-nowrap ${
                  selectedChild === index
                    ? "border-primary bg-primary-50 shadow-card"
                    : "border-neutral-200 hover:border-neutral-300"
                }`}
              >
                <Avatar name={c.name} size="sm" />
                <div className="text-left">
                  <p className="font-semibold text-neutral-900 text-sm">
                    {c.name}
                  </p>
                  <p className="text-xs text-neutral-600">{c.vanNumber}</p>
                </div>
              </button>
            ))}
          </div>

          <div className="grid lg:grid-cols-3 gap-6">
            {/* Live Map */}
            <div className="lg:col-span-2">
              {/* Map Placeholder */}
              <Card className="h-96 relative overflow-hidden">
                <CardContent className="p-0 h-full">
                  <div className="h-full bg-gradient-to-br from-primary-50 to-secondary-50 flex items-center justify-center relative">
                    <div className="text-center">
                      <div className="w-16 h-16 bg-white/20 rounded-full flex items-center justify-center mx-auto mb-4">
                        <MapPin className="w-8 h-8 text-primary" />
                      </div>
                      <h3 className="text-lg font-semibold text-neutral-900 mb-2">
                        Live Tracking
                      </h3>
                      <p className="text-sm text-neutral-600 mb-4">
                        Real-time van location tracking
                      </p>

                      {/* Van Location Indicator */}
                      <div className="absolute top-1/2 left-1/2 transform -translate-x-1/2 -translate-y-1/2">
                        <div className="w-12 h-12 bg-primary rounded-full flex items-center justify-center shadow-lg animate-pulse">
                          <Navigation className="w-6 h-6 text-white" />
                        </div>
                      </div>

                      {/* Route Path */}
                      <div className="absolute inset-0 flex items-center justify-center">
                        <svg className="w-full h-full" viewBox="0 0 400 300">
                          {/* Route line */}
                          <path
                            d="M50 250 Q200 150 350 50"
                            stroke="rgba(0, 184, 212, 0.3)"
                            strokeWidth="3"
                            fill="none"
                          />
                          {/* Pickup points */}
                          <circle cx="50" cy="250" r="4" fill="#00B8D4" />
                          <circle cx="150" cy="200" r="4" fill="#00B8D4" />
                          <circle cx="250" cy="150" r="4" fill="#00B8D4" />
                          <circle cx="350" cy="50" r="4" fill="#00B8D4" />
                        </svg>
                      </div>
                    </div>
                  </div>
                </CardContent>
              </Card>

              {/* Route Progress */}
              <Card className="mt-6">
                <CardHeader>
                  <CardTitle>Route Progress</CardTitle>
                  <CardDescription>
                    Track all stops on the route
                  </CardDescription>
                </CardHeader>
                <CardContent>
                  <div className="space-y-4">
                    {child.stops.map((stop, index) => (
                      <div key={index} className="flex items-start gap-4">
                        {/* Timeline Indicator */}
                        <div className="flex flex-col items-center">
                          <div
                            className={`w-10 h-10 rounded-full flex items-center justify-center ${
                              stop.status === "completed"
                                ? "bg-green-100"
                                : stop.status === "upcoming"
                                  ? "bg-primary-100"
                                  : "bg-neutral-200"
                            }`}
                          >
                            {stop.status === "completed" ? (
                              <CheckCircle className="w-5 h-5 text-green-600" />
                            ) : stop.status === "upcoming" ? (
                              <MapPin className="w-5 h-5 text-primary" />
                            ) : (
                              <Clock className="w-5 h-5 text-neutral-400" />
                            )}
                          </div>
                          {index < child.stops.length - 1 && (
                            <div
                              className={`w-0.5 h-12 ${
                                stop.status === "completed"
                                  ? "bg-green-300"
                                  : "bg-neutral-200"
                              }`}
                            />
                          )}
                        </div>

                        {/* Stop Details */}
                        <div className="flex-1 pb-4">
                          <div className="flex items-start justify-between mb-1">
                            <div>
                              <h4 className="font-semibold text-neutral-900">
                                {stop.location}
                              </h4>
                              <p className="text-sm text-neutral-600">
                                {stop.student}
                              </p>
                            </div>
                            <Badge
                              variant={
                                stop.status === "completed"
                                  ? "success"
                                  : stop.status === "upcoming"
                                    ? "warning"
                                    : "secondary"
                              }
                              className="text-xs"
                            >
                              {stop.status === "completed"
                                ? "Completed"
                                : stop.status === "upcoming"
                                  ? "Next Stop"
                                  : "Pending"}
                            </Badge>
                          </div>
                          <div className="flex items-center gap-2 text-xs text-neutral-500">
                            <Clock className="w-3 h-3" />
                            <span>{stop.time}</span>
                          </div>
                        </div>
                      </div>
                    ))}
                  </div>
                </CardContent>
              </Card>
            </div>

            {/* Right Sidebar */}
            <div>
              {/* Driver Info */}
              <Card>
                <CardHeader>
                  <CardTitle>Driver Information</CardTitle>
                </CardHeader>
                <CardContent>
                  <div className="flex items-center gap-3 mb-4">
                    <Avatar name={child.driver} size="xl" />
                    <div>
                      <h4 className="font-semibold text-neutral-900">
                        {child.driver}
                      </h4>
                      <div className="flex items-center gap-1 mt-1">
                        <Star className="w-4 h-4 fill-highlight text-highlight" />
                        <span className="text-sm font-medium">
                          {child.driverRating}
                        </span>
                        <span className="text-xs text-neutral-500">
                          (120 reviews)
                        </span>
                      </div>
                    </div>
                  </div>

                  <div className="space-y-3">
                    <div className="flex items-center gap-2 text-sm">
                      <MapPin className="w-4 h-4 text-neutral-500" />
                      <span className="text-neutral-700">
                        {child.vanNumber}
                      </span>
                    </div>
                    <div className="flex items-center gap-2 text-sm">
                      <Phone className="w-4 h-4 text-neutral-500" />
                      <span className="text-neutral-700">
                        {child.driverPhone}
                      </span>
                    </div>
                  </div>

                  <div className="mt-4 pt-4 border-t border-neutral-200 space-y-2">
                    <Button variant="primary" className="w-full">
                      <Phone className="w-4 h-4" />
                      Call Driver
                    </Button>
                    <Button variant="outline" className="w-full">
                      <MessageSquare className="w-4 h-4" />
                      Send Message
                    </Button>
                  </div>
                </CardContent>
              </Card>

              {/* Trip Status */}
              <Card className="mt-6">
                <CardHeader>
                  <CardTitle>Trip Status</CardTitle>
                </CardHeader>
                <CardContent>
                  <div className="space-y-4">
                    <div className="flex items-center justify-between">
                      <span className="text-sm text-neutral-600">Status</span>
                      <Badge
                        variant="success"
                        className="flex items-center gap-1"
                      >
                        <span className="status-dot status-active animate-pulse" />
                        On Route
                      </Badge>
                    </div>
                    <div className="flex items-center justify-between">
                      <span className="text-sm text-neutral-600">ETA</span>
                      <span className="text-sm font-semibold text-neutral-900">
                        {child.eta}
                      </span>
                    </div>
                    <div className="flex items-center justify-between">
                      <span className="text-sm text-neutral-600">Distance</span>
                      <span className="text-sm font-semibold text-neutral-900">
                        {child.distance}
                      </span>
                    </div>
                    <div className="flex items-center justify-between">
                      <span className="text-sm text-neutral-600">
                        Next Stop
                      </span>
                      <span className="text-sm font-semibold text-neutral-900">
                        Your Location
                      </span>
                    </div>
                  </div>
                </CardContent>
              </Card>

              {/* Notifications */}
              <Card className="mt-6">
                <CardHeader>
                  <CardTitle>Recent Updates</CardTitle>
                </CardHeader>
                <CardContent>
                  <div className="space-y-3">
                    <div className="flex items-start gap-3 p-3 bg-green-50 rounded-lg">
                      <CheckCircle className="w-5 h-5 text-green-600 flex-shrink-0 mt-0.5" />
                      <div>
                        <p className="text-sm font-medium text-neutral-900">
                          Van departed
                        </p>
                        <p className="text-xs text-neutral-600">
                          5 minutes ago
                        </p>
                      </div>
                    </div>
                    <div className="flex items-start gap-3 p-3 bg-secondary-50 rounded-lg">
                      <Navigation className="w-5 h-5 text-secondary flex-shrink-0 mt-0.5" />
                      <div>
                        <p className="text-sm font-medium text-neutral-900">
                          2 stops completed
                        </p>
                        <p className="text-xs text-neutral-600">On schedule</p>
                      </div>
                    </div>
                    <div className="flex items-start gap-3 p-3 bg-highlight-50 rounded-lg">
                      <AlertCircle className="w-5 h-5 text-highlight flex-shrink-0 mt-0.5" />
                      <div>
                        <p className="text-sm font-medium text-neutral-900">
                          Approaching your location
                        </p>
                        <p className="text-xs text-neutral-600">
                          ETA: 8 minutes
                        </p>
                      </div>
                    </div>
                  </div>
                </CardContent>
              </Card>
            </div>
          </div>
        </main>
      </div>
    </div>
  );
}
